#include "umicom/studio/database_explorer_commands.h"
#include <stdio.h>
#include <string.h>
static const UmiStudioDatabaseCommand commands[UMI_STUDIO_DATABASE_COMMAND_COUNT]={{"database.snapshot","Show Database Snapshot",0},{"database.pane.activate","Activate Database Pane",1},{"database.write-mode.enable","Enable Governed Writes",1},{"database.write-mode.disable","Disable Governed Writes",1},{"database.transaction.begin","Begin Database Transaction",1},{"database.transaction.commit","Commit Database Transaction",1},{"database.transaction.rollback","Roll Back Database Transaction",1},{"database.query.execute","Execute Database Query",1},{"database.history.clear","Clear Query History",1},{"database.schema.refresh","Refresh Database Schema",1}};
size_t umi_studio_database_commands_count(void){return UMI_STUDIO_DATABASE_COMMAND_COUNT;}
const UmiStudioDatabaseCommand *umi_studio_database_command_at(size_t i){return i<UMI_STUDIO_DATABASE_COMMAND_COUNT?&commands[i]:NULL;}
UmiStatus umi_studio_database_command_execute(UmiStudioDatabaseExplorerCentre *c,const char *id,const char *arg,char *m,size_t cap){UmiStatus s=UMI_STATUS_NOT_FOUND;UmiDatabaseQueryResult result;UmiStudioDatabaseExplorerSnapshot snap;if(c==NULL||id==NULL)return UMI_STATUS_INVALID_ARGUMENT;if(strcmp(id,"database.snapshot")==0)s=umi_studio_database_explorer_snapshot(c,&snap);else if(strcmp(id,"database.pane.activate")==0)s=arg!=NULL?umi_studio_database_explorer_activate(c,arg):UMI_STATUS_INVALID_ARGUMENT;else if(strcmp(id,"database.write-mode.enable")==0)s=umi_studio_database_explorer_set_write_mode(c,1);else if(strcmp(id,"database.write-mode.disable")==0)s=umi_studio_database_explorer_set_write_mode(c,0);else if(strcmp(id,"database.transaction.begin")==0)s=umi_studio_database_transaction_begin(c);else if(strcmp(id,"database.transaction.commit")==0)s=umi_studio_database_transaction_commit(c);else if(strcmp(id,"database.transaction.rollback")==0)s=umi_studio_database_transaction_rollback(c);else if(strcmp(id,"database.query.execute")==0)s=arg!=NULL?umi_studio_database_query_execute(c,arg,&result):UMI_STATUS_INVALID_ARGUMENT;else if(strcmp(id,"database.history.clear")==0){umi_database_query_history_clear(&c->explorer->queries.history);c->revision+=1U;s=UMI_STATUS_OK;}else if(strcmp(id,"database.schema.refresh")==0){if(c->explorer->schema.table_count>0U)c->explorer->schema.tables[0].estimated_rows=umi_data_server_count(c->explorer->server);c->explorer->schema.revision+=1U;c->revision+=1U;s=UMI_STATUS_OK;}if(m!=NULL&&cap>0U)(void)snprintf(m,cap,"Database command %s: %s",id,umi_status_text(s));return s;}
